/**
 * Replaces test-run artefacts in dealer trading names with realistic South African identities.
 *
 * 73 of 128 dealerships carried names generated by automated test runs — "Surf Auto
 * pcp001e-1785347218556-6598", "Surf Auto cctrace-1783326360348". These are the dealer names shown
 * on every vehicle card in the marketplace, so internal test IDs were the most prominent text on
 * the homepage after the price.
 *
 * Names are derived deterministically from the dealership id, so a given dealer always receives the
 * same identity and re-running changes nothing.
 *
 * Usage: node scripts/seed/repair-dealer-identity.mjs [--dry-run]
 */
import { readFileSync } from "node:fs";
import { createClient } from "@supabase/supabase-js";

const DRY_RUN = process.argv.includes("--dry-run");

for (const line of readFileSync(".env.local", "utf8").split(/\r?\n/)) {
  const match = line.match(/^([A-Z_0-9]+)=(.*)$/);
  if (match) process.env[match[1]] ??= match[2].trim();
}

const supabase = createClient(
  process.env.NEXT_PUBLIC_SUPABASE_URL,
  process.env.SUPABASE_SECRET_KEY,
  { auth: { persistSession: false } },
);

/** A trading name is an artefact if it carries a test prefix or a raw timestamp. */
const isArtefact = (name) =>
  /pcp\d{3}|cctrace|ccpost|\d{10,}|^test\b/i.test(String(name ?? "").trim());

/** Name parts that read as genuine South African dealer groups. */
const PREFIXES = [
  "Atlantic", "Table Bay", "Sandton", "Umhlanga", "Kyalami", "Constantia", "Rosebank",
  "Ballito", "Stellenbosch", "Midrand", "Century City", "Bryanston", "Somerset",
  "Pretoria East", "Fourways", "Claremont", "Waterfall", "Menlyn", "Tygerberg", "Gqeberha",
];

const SUFFIXES = [
  "Motor Group", "Auto", "Motors", "Automotive", "Car Company", "Vehicle Centre",
  "Auto Gallery", "Prestige Cars", "Motor Works", "Select Cars",
];

function hash(value) {
  let h = 2166136261;
  for (let i = 0; i < value.length; i += 1) {
    h ^= value.charCodeAt(i);
    h = Math.imul(h, 16777619);
  }
  return Math.abs(h);
}

async function main() {
  const { data: dealers, error } = await supabase
    .from("dealerships")
    .select("id, trading_name, business_name, city")
    .order("id");
  if (error) throw new Error(error.message);

  const affected = dealers.filter((d) => isArtefact(d.trading_name));
  console.log(`${dealers.length} dealerships, ${affected.length} with test artefacts`);

  // Keep names unique across the marketplace — two identical dealer names read as a data bug.
  const taken = new Set(
    dealers.filter((d) => !isArtefact(d.trading_name)).map((d) => d.trading_name),
  );

  const updates = [];
  for (const dealer of affected) {
    const seed = hash(dealer.id);
    let name = "";
    for (let attempt = 0; attempt < 64; attempt += 1) {
      const prefix = PREFIXES[(seed + attempt * 7) % PREFIXES.length];
      const suffix = SUFFIXES[(seed + attempt * 13) % SUFFIXES.length];
      name = `${prefix} ${suffix}`;
      if (!taken.has(name)) break;
    }
    taken.add(name);
    updates.push({ id: dealer.id, from: dealer.trading_name, to: name });
  }

  updates.slice(0, 8).forEach((u) => console.log(`  ${u.from.slice(0, 38).padEnd(40)} → ${u.to}`));
  if (updates.length > 8) console.log(`  … and ${updates.length - 8} more`);

  if (DRY_RUN) {
    console.log("\n--dry-run: nothing written.");
    return;
  }

  for (const update of updates) {
    const { error: updateError } = await supabase
      .from("dealerships")
      .update({ trading_name: update.to, business_name: `${update.to} (Pty) Ltd` })
      .eq("id", update.id);
    if (updateError) throw new Error(`${update.id}: ${updateError.message}`);
  }

  console.log(`\nRenamed ${updates.length} dealership(s).`);
}

main().catch((error) => {
  console.error(error);
  process.exit(1);
});
